const fs = require('fs-extra');
const path = require('path');




function mergeSystem(nodes, tree, path) {
    var first = nodes.shift()
    if (!tree[first]) {
        tree[first] = {}
        if (tree["$className"] != "DataModel") {
            if (nodes.length != 0) {
                tree[first]["$className"] = "Folder"
            }
        }
    }

    if (nodes.length != 0) {
        mergeSystem(nodes, tree[first], path)
    } else {
        tree[first]["$path"] = path
    }
}


function createNodesByRoot(root, subNodes) {
    var nodes
    if (root == "StarterPlayerScripts") {
        nodes = ["tree", "StarterPlayer", "StarterPlayerScripts", "Systems"]
    }
    else if (root == "StarterCharacterScripts") {
        nodes = ["tree", "StarterPlayer", "StarterCharacterScripts", "Systems"]
    }
    else if (!root) {
        nodes = ["tree", "ReplicatedStorage", "Systems"]
    }
    else {
        nodes = ["tree", root, "Systems"]
    }

    for (const subNode of subNodes) {
        nodes.push(subNode)
    }

    return nodes
}

function createSystemNodes(systems) {
    var nodesList = []
    // foreach in system(object)
    for (const key in systems) {
        var system = systems[key]

        // 不在系统目录内的不用生成rojo
        if (!system.IsInSystemRoot) {
            continue
        }
        // var nodes = createNodesByRoot(system.Root, system.NodesFromRoot)
        var filePath = system.FilePath.replace(/\\/g, '/');
        // nodesList.push({
        //     FilePath: filePath,
        //     Nodes: nodes
        // })

        var ignoreDirs = system.AltDirs

        for (const ignoreDir of ignoreDirs) {
            var dir = ignoreDir.Rename.replace(filePath + "/", "")
            var nodes = createNodesByRoot(ignoreDir.Target, [...system.NodesFromRoot, ...dir.split("/")])
            nodesList.push({
                FilePath: ignoreDir.Path,
                Nodes: nodes
            })
        }
    }
    return nodesList
}

function getSystemsRojoTree(rojoTree, nodesList) {
    for (const nodes of nodesList) {
        mergeSystem(nodes.Nodes, rojoTree, nodes.FilePath)
    }
    return rojoTree
}



function updateIgnores(systems, rojoTree) {
    if (!rojoTree["globIgnorePaths"]) {
        rojoTree["globIgnorePaths"] = []
    }
    for (const path in systems) {
        var system = systems[path]
        var ignoreDirs = system.AltDirs
        for (const ignoreDir of ignoreDirs) {
            rojoTree["globIgnorePaths"].push(ignoreDir.Path)
        }
    }
}


function getSystemRoot(systemRoot) {
    var nodes = createNodesByRoot("ReplicatedStorage", [])
    return {
        FilePath: systemRoot,
        Nodes: nodes
    }
}

function gen(templatePath, outputPath, config, systemRoot) {

    var systems = config.GetSystems()


    var templateContext = fs.readFileSync(templatePath, 'utf-8')
    var rojoTree = JSON.parse(templateContext)

    var nodesList = createSystemNodes(systems, systemRoot)

    nodesList.push(getSystemRoot(systemRoot))

    var newRojoTree = getSystemsRojoTree(rojoTree, nodesList)

    updateIgnores(systems, newRojoTree)

    fs.writeFileSync(outputPath, JSON.stringify(newRojoTree, null, 2), 'utf-8')
    console.log(`write file ${outputPath}`)
}


module.exports = gen;